let current=lessons.find(e=>e.id===state.lastExercise)||lessons[0],view=state.view,hand=state.hand||'both',mode=state.mode||'free',bpm=state.bpm||60,sub=1,page='practicar',playing=false,ctx=null,run=0,timer=null,scheduled=[],metro=false,metroBeat=0,metMeter='4/4',metSub=1,volume=state.volume??.5,loop=false,midiAccess=null,midiStatus='Sin conectar',held=new Set(),capture=null,menu=false;
const names=['Do','Do♯','Re','Re♯','Mi','Fa','Fa♯','Sol','Sol♯','La','La♯','Si'],letters=['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'];
function noteName(p,oct=true){return (state.names==='letters'?letters:names)[p%12]+(oct?Math.floor(p/12)-1:'')}
function listEvents(ex=current,which=hand){let result=[];for(const h of ['r','l']){if(which==='r'&&h==='l'||which==='l'&&h==='r')continue;let t=0;for(const [i,n] of (ex[h]||[]).entries()){result.push({...n,t,hand:h,index:i,id:h+i});t+=n.d}}return result.sort((a,b)=>a.t-b.t)}
function length(ex=current){return Math.max(...['r','l'].map(h=>(ex[h]||[]).reduce((t,n)=>t+n.d,0)))}
function groups(){const g=new Map;for(const e of listEvents())if(e.p!==null){if(!g.has(e.t))g.set(e.t,{t:e.t,notes:[],ids:[]});g.get(e.t).notes.push(...(Array.isArray(e.p)?e.p:[e.p]));g.get(e.t).ids.push(e.id)}return [...g.values()]}
function audio(){if(!ctx)ctx=new AudioContext;ctx.resume();return ctx}
function tone(p,time,d=.35,vel=.6){const a=audio(),o=a.createOscillator(),g=a.createGain();o.type='triangle';o.frequency.value=440*2**((p-69)/12);g.gain.setValueAtTime(0,time);g.gain.linearRampToValueAtTime(.17*vel*volume,time+.008);g.gain.exponentialRampToValueAtTime(.001,time+Math.max(.05,d));o.connect(g).connect(a.destination);o.start(time);o.stop(time+Math.max(.05,d)+.02);scheduled.push(o)}
function click(time,accent=false){const a=audio(),o=a.createOscillator(),g=a.createGain();o.frequency.value=accent?1400:950;g.gain.setValueAtTime(volume*.18,time);g.gain.exponentialRampToValueAtTime(.001,time+.035);o.connect(g).connect(a.destination);o.start(time);o.stop(time+.04);scheduled.push(o)}
function later(fn,ms){const t=setTimeout(fn,ms);runTimers.push(t)}let runTimers=[];
function stop(){run++;playing=false;metro=false;clearInterval(timer);runTimers.forEach(clearTimeout);runTimers=[];scheduled.forEach(o=>{try{o.stop()}catch{}});scheduled=[];$$('.lit,.current,.beat.on').forEach(el=>el.classList.remove('lit','current','on'));const b=$('#play');if(b)b.textContent='▶ Escuchar';capture=null;const mp=$('#midi-practice');if(mp)mp.textContent='◎ Practicar con MIDI';const m=$('#metro-start');if(m)m.textContent='▶ Iniciar metrónomo';}
function highlight(e){$$('.current').forEach(x=>x.classList.remove('current'));for(const id of e.ids||[e.id])document.querySelectorAll('[data-note="'+id+'"]').forEach(x=>x.classList.add('current'));$$('.lit').forEach(x=>x.classList.remove('lit'));const ps=e.notes||(Array.isArray(e.p)?e.p:[e.p]);ps.forEach(p=>$$('[data-key="'+p+'"]').forEach(x=>x.classList.add('lit')))}
function play(){if(playing){stop();return}stop();audio();playing=true;const token=run;$('#play').textContent='■ Detener';const beatDur=60/bpm,unit=current.meter[1]===8?1.5:1,quarter=beatDur/unit,bar=current.meter[0]*4/current.meter[1],start=ctx.currentTime+.12+bar*quarter;let events=listEvents(),end=length();let nextClick=0,i=0;const total=end+bar;timer=setInterval(()=>{if(token!==run)return;const until=ctx.currentTime+.12;while(nextClick*quarter+start-bar*quarter<until&&nextClick<total){const t=start-bar*quarter+nextClick*quarter;click(t,Math.abs(nextClick%bar)<.001);nextClick+=unit/sub}while(i<events.length&&start+events[i].t*quarter<until){const e=events[i++],time=start+e.t*quarter;if(e.p!==null)(Array.isArray(e.p)?e.p:[e.p]).forEach(p=>tone(p,time,e.d*quarter*.9));later(()=>{if(token===run)highlight(e)},Math.max(0,(time-ctx.currentTime)*1000))}if(ctx.currentTime>start+end*quarter+.1){stop();if(loop&&page==='practicar')play()}},25)}
function pianoSvg(){const whites=Array.from({length:22},(_,i)=>'<rect x="'+(28+i*15)+'" y="78" width="14" height="69" rx="2" fill="#f9f7fc"/>').join('');const blacks=Array.from({length:21},(_,i)=>[0,1,3,4,5].includes(i%7)?'<rect x="'+(38+i*15)+'" y="78" width="9" height="42" rx="2" fill="#24202e"/>':'').join('');return '<svg viewBox="0 0 400 200" aria-label="Ilustración de un teclado de piano"><rect x="12" y="35" width="370" height="125" rx="12" fill="#201b2b"/><rect x="22" y="44" width="350" height="25" rx="5" fill="#30273f"/><g fill="#a184bd"><circle cx="162" cy="55" r="4"/><circle cx="177" cy="55" r="4"/><circle cx="192" cy="55" r="4"/></g><rect x="211" y="48" width="35" height="14" rx="3" fill="#9e82c8"/><path d="M34 54h102m126 0h94" stroke="#665773" stroke-width="4" stroke-dasharray="2 3"/>'+whites+blacks+'</svg>'}
function keyboard(){let html='';let whites=[];for(let p=48;p<=76;p++)if(![1,3,6,8,10].includes(p%12))whites.push(p);whites.forEach(p=>html+='<button class="white-key" data-key="'+p+'" aria-label="Tocar '+noteName(p)+'"><span>'+noteName(p)+'</span></button>');for(let p=48;p<=76;p++)if([1,3,6,8,10].includes(p%12)){let n=whites.filter(w=>w<p).length;html+='<button class="black-key" data-key="'+p+'" aria-label="Tocar '+noteName(p)+'" style="left:calc('+(n/whites.length*100)+'% - 2.25%)"></button>'}return '<div class="keyboard">'+html+'</div><p class="tiny muted">Teclado de referencia · Do3–Mi5 · Pulsa una tecla para escucharla</p>'}
function guide(){let out='';for(const h of ['r','l']){if(hand==='r'&&h==='l'||hand==='l'&&h==='r'||!current[h])continue;out+='<div class="guide"><div class="guide-hand">'+(h==='r'?'MD':'MI')+'</div><div class="guide-events">';let time=0;for(const [i,e] of current[h].entries()){let label=e.p===null?'S':(Array.isArray(e.p)?e.p:[e.p]).map(p=>noteName(p)).join(' + ');out+='<div class="note-cell" data-note="'+h+i+'" style="flex:'+e.d+'"><small>'+((time%(current.meter[0]*4/current.meter[1]))+1)+'</small><strong>'+label+'</strong><small>'+e.d+' ♩'+(e.f?' · dedo '+e.f:'')+'</small></div>';time+=e.d}out+='</div></div>'}return '<div class="notation">'+out+'</div><p class="tiny muted">MD: derecha · MI: izquierda · S: silencio · Duraciones expresadas en negras (♩). En 6/8 cada pulso grande dura 1,5 negras.</p>'}
function staff(){let bar=current.meter[0]*4/current.meter[1],len=length(),bars=Math.ceil(len/bar),bw=190,w=90+bars*bw;let svg='<svg role="img" aria-label="Partitura en Do mayor, '+current.meter.join('/')+'" width="'+w+'" height="255" viewBox="0 0 '+w+' 255"><rect width="100%" height="100%" fill="white"/>';const diat=p=>Math.floor(p/12)*7+({0:0,2:1,4:2,5:3,7:4,9:5,11:6}[p%12]??0);for(const h of ['r','l']){if(hand==='r'&&h==='l'||hand==='l'&&h==='r')continue;const base=h==='r'?90:210,ref=h==='r'?64:43;for(let j=0;j<5;j++)svg+='<line x1="15" y1="'+(base-j*10)+'" x2="'+(w-5)+'" y2="'+(base-j*10)+'" stroke="#b9b1c1"/>';svg+='<text x="22" y="'+(base-6)+'" font-size="48" font-family="serif">'+(h==='r'?'𝄞':'𝄢')+'</text><text x="63" y="'+(base-22)+'" text-anchor="middle" font-family="serif" font-size="17">'+current.meter[0]+'</text><text x="63" y="'+(base-4)+'" text-anchor="middle" font-family="serif" font-size="17">'+current.meter[1]+'</text>';for(let b=0;b<=bars;b++)svg+='<line x1="'+(82+b*bw)+'" x2="'+(82+b*bw)+'" y1="'+(base-40)+'" y2="'+base+'" stroke="#b9b1c1"/>';let t=0;for(const [i,e] of (current[h]||[]).entries()){const x=102+Math.floor(t/bar)*bw+(t%bar)/bar*(bw-30);svg+='<g data-note="'+h+i+'" fill="#493655" stroke="#493655">';if(e.p===null)svg+='<text x="'+x+'" y="'+(base-10)+'" font-size="23" stroke="none">'+(e.d>=2?'𝄼':'𝄽')+'</text>';else{const ps=Array.isArray(e.p)?e.p:[e.p];let ys=ps.map(p=>base-(diat(p)-diat(ref))*5);for(const y of ys){if(y>base)for(let ly=base+10;ly<=y;ly+=10)svg+='<line x1="'+(x-10)+'" x2="'+(x+10)+'" y1="'+ly+'" y2="'+ly+'"/>';if(y<base-40)for(let ly=base-50;ly>=y;ly-=10)svg+='<line x1="'+(x-10)+'" x2="'+(x+10)+'" y1="'+ly+'" y2="'+ly+'"/>';svg+='<ellipse cx="'+x+'" cy="'+y+'" rx="6" ry="4" transform="rotate(-18 '+x+' '+y+')" fill="'+(e.d>=2?'white':'#493655')+'" stroke-width="1.5"/>';if(e.d===1.5||e.d===3)svg+='<circle cx="'+(x+11)+'" cy="'+(y-2)+'" r="1.6"/>'}if(e.d<4){const y=Math.min(...ys);svg+='<line x1="'+(x+5)+'" y1="'+y+'" x2="'+(x+5)+'" y2="'+(y-28)+'" stroke-width="1.5"/>';if(e.d<1)svg+='<path d="M'+(x+5)+' '+(y-28)+' q14 7 4 17" fill="none" stroke-width="2"/>'}if(e.f)svg+='<text x="'+x+'" y="'+(Math.min(...ys)-36)+'" text-anchor="middle" font-size="10" stroke="none">'+e.f+'</text>'}svg+='</g>';t+=e.d}}return '<div class="notation">'+svg+'</svg></div>'}
function nav(){const el=$('#nav');el.innerHTML=pages.map(([id,icon,label])=>'<button class="nav-item '+(page===id?'active':'')+'" data-page="'+id+'">'+navIcon(id)+'<span>'+label+'</span></button>').join('');$$('.bottom-nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb').textContent=pages.find(x=>x[0]===page)?.[2]||'Configuración'}
function render(){nav();const profileButton=$('#profile-switch');if(profileButton){profileButton.innerHTML='<span>'+esc(profiles.profile().avatar)+'</span><span>'+esc(profiles.profile().name)+'</span>';profileButton.setAttribute('aria-label','Cambiar perfil: '+profiles.profile().name)}const c=$('#content');if(page==='practicar')c.innerHTML=practice();if(page==='aia')c.innerHTML=aia();if(page==='recorrido')c.innerHTML=course();if(page==='armonia')c.innerHTML=harmony();if(page==='ritmo')c.innerHTML=rhythm();if(page==='canciones')c.innerHTML=songs();if(page==='biblioteca'){c.innerHTML=library();loadFiles()}if(page==='progreso')c.innerHTML=progress();if(page==='profesor')c.innerHTML=teacher();if(page==='config')c.innerHTML=config();if(page==='perfiles')c.innerHTML=profilePage();bind();}
function practice(){return '<section class="hero"><div class="hero-copy"><div class="eyebrow">TU MOMENTO AL PIANO</div><h1>Una tecla. Un comienzo.<br>Tu próxima melodía.</h1><p>Escucha, descubre y toca a tu ritmo.<br>El siguiente paso está más cerca de lo que crees.</p><button class="btn light" data-page="aia">AIA · Preparar mi práctica →</button></div><div class="hero-art">'+pianoSvg()+'<span>88 TECLAS · INFINITAS POSIBILIDADES</span></div></section><div class="section-title"><h2>Vamos a tocar</h2><small>Sin solfeo previo · Con partitura si lo prefieres</small></div><section class="card"><div class="row between"><span class="pill">ETAPA '+current.stage+' · '+current.tag+'</span><div class="tabs" id="view-tabs">'+[['guide','Guía / tablatura'],['score','Partitura'],['both','Ambas']].map(([v,l])=>'<button data-view="'+v+'" class="'+(view===v?'selected':'')+'">'+l+'</button>').join('')+'</div></div><div class="controls"><label class="field">EJERCICIO<select id="exercise">'+lessons.map(e=>'<option value="'+e.id+'" '+(e===current?'selected':'')+'>'+e.title+'</option>').join('')+'</select></label><label class="field">MANOS<select id="hand"><option value="both">Ambas manos</option><option value="r" '+(hand==='r'?'selected':'')+'>Derecha</option><option value="l" '+(hand==='l'?'selected':'')+'>Izquierda</option></select></label><label class="field">PRÁCTICA<select id="mode"><option value="free">A mi ritmo</option><option value="timed" '+(mode==='timed'?'selected':'')+'>Con tempo · MIDI</option></select></label><label class="field">'+(current.meter[1]===8?'♩.':'♩')+' = BPM<input id="bpm" type="number" min="30" max="300" value="'+bpm+'"></label></div><h2 class="exercise-title">'+current.title+'</h2><p class="muted tiny">'+current.desc+' · Compás '+current.meter.join('/')+'</p>'+(view!=='score'?guide():'')+(view!=='guide'?staff():'')+keyboard()+'<div class="transport"><button class="btn primary" id="play">▶ Escuchar</button><button class="btn" id="midi-practice">◎ Practicar con MIDI</button><label class="tiny"><input type="checkbox" id="loop" '+(loop?'checked':'')+'> Repetir</label><label class="tiny">Subdivisión <select id="sub"><option>1</option><option '+(sub===2?'selected':'')+'>2</option><option '+(sub===3?'selected':'')+'>3</option></select></label><span class="status" id="practice-status">'+esc(midiStatus)+'</span></div><div class="callout">'+current.tip+'</div><div class="row between"><span class="tiny muted">¿Lo has practicado en tu piano? Guarda tu valoración.</span><button class="btn" id="rate">Valorar mi práctica →</button></div><div id="rating"></div></section><div class="grid two"><div class="card"><span class="eyebrow">EL PULSO ES TU ALIADO</span><h3 style="margin-top:10px">Primero cómodo. Después fluido.</h3><p class="tiny muted">Trabaja un fragmento despacio y conserva el pulso. Aumenta el tempo cuando sientas estabilidad.</p><button class="btn" data-page="ritmo">Abrir metrónomo →</button></div><div class="card"><span class="eyebrow">CONOCE TU INSTRUMENTO</span><h3 style="margin-top:10px">Tu VEVOR, listo para aprender</h3><p class="tiny muted">Comprueba sensibilidad, transposición y modo de teclado antes de empezar.</p><button class="btn" data-page="config">Preparar mi piano →</button></div></div>'}
function recommendation(){const last=state.attempts.at(-1);if(last?.source==='midi'&&(last.hits/last.total<.85||(last.mode==='timed'&&last.timing<85)))return {lesson:lessons.find(e=>e.id===last.id)||lessons[0],reason:'La última toma MIDI sugiere repasar este objetivo. Comprueba la conexión y prueba más despacio o con una mano; una toma aislada no define tu nivel.'};if(last?.rating==='dificil')return {lesson:lessons.find(e=>e.id===last.id)||lessons[0],reason:'Tu última valoración fue «Me cuesta». Repetimos el objetivo con calma; puedes bajar el tempo o separar las manos.'};let next=lessons.find(e=>!state.attempts.some(a=>a.id===e.id));if(next)return {lesson:next,reason:'Este ejercicio todavía no tiene práctica registrada. Es el siguiente contenido del recorrido inicial.'};return {lesson:lessons.slice().sort((a,b)=>(state.attempts.filter(x=>x.id===a.id).at(-1)?.at||0)-(state.attempts.filter(x=>x.id===b.id).at(-1)?.at||0))[0],reason:'Recuperamos uno de los ejercicios que llevas más tiempo sin revisar.'}}
function aia(){const rec=recommendation();let mins=Number(state.duration),parts=[Math.max(1,Math.round(mins*.13)),Math.max(2,Math.round(mins*.2)),Math.round(mins*.34)];parts.push(mins-parts.reduce((a,b)=>a+b,0));return '<div class="eyebrow">APRENDIZAJE INTERACTIVO ADAPTATIVO</div><h1>AIA · Tu próxima práctica</h1><p class="intro">Un recorrido que se adapta a ti: repasa, practica y avanza según tus resultados.</p><div class="aia-banner"><span class="pill">TU OBJETIVO DE HOY</span><h2 style="margin-top:16px">'+rec.lesson.title+'</h2><p>'+rec.reason+'</p><div class="row"><label>Tiempo disponible <select id="duration">'+[10,15,20,30].map(n=>'<option '+(n===mins?'selected':'')+'>'+n+'</option>').join('')+'</select> minutos</label></div></div><div class="card">'+[['Preparar mi piano','Postura, sonido y pulso. Revisa la configuración del VEVOR.','config'],['Repasar','Vuelve a una base sencilla y escucha con atención.','primeras'],['Trabajar el objetivo',rec.lesson.title,rec.lesson.id],['Aplicarlo musicalmente','Toca una pequeña pieza y valora cómo te has sentido.','vals']].map(([title,desc,target],i)=>'<div class="plan-step"><span class="step-number">'+(i+1)+'</span><div><h3>'+title+' <span class="tiny muted">· '+parts[i]+' min</span></h3><p>'+desc+'</p></div><button class="btn '+(i===2?'primary':'')+'" '+(target==='config'?'data-page="config"':'data-ex="'+target+'"')+'>Abrir →</button></div>').join('')+'</div><div class="callout">AIA v1 utiliza tu historial local y dificultad declarada. Los resultados MIDI se conservan aparte. No asigna niveles acreditados ni considera una autoevaluación como medición. Puedes elegir cualquier ejercicio desde Mi recorrido.</div>'}
const stages=[['Conozco mi piano','Preparación, postura, notas y pulso.'],['Primeras melodías','Cinco dedos, manos separadas, duraciones y silencios.'],['Coordinación y lectura','Dos manos, corcheas y compás ternario.'],['Base armónica','Tríadas, inversiones y compases compuestos.'],['Nivel medio','Arpegios, acompañamiento, pedal y fraseo.'],['Medio consolidado','Síncopas, séptimas, transposición e improvisación.'],['Avanzado aficionado','Voces, equilibrio, arreglos y autonomía musical.']];
function course(){return '<div class="eyebrow">PASO A PASO</div><h1>Mi recorrido</h1><p class="intro">Una base sólida para tocar con autonomía. Elige dónde empezar; el ritmo lo marcas tú.</p><div class="card">'+stages.map(([t,d],i)=>{const ls=lessons.filter(e=>e.stage===i);return '<div class="course-stage"><h3><span>'+i+'. '+t+'</span><span class="pill">'+(i===0?'Preparación':ls.length+' ejercicios')+'</span></h3><p>'+d+'</p><div class="row">'+(i===0?'<button class="btn" data-page="config">Preparar mi piano →</button>':ls.map(e=>'<button class="btn" data-ex="'+e.id+'">'+e.title+' →</button>').join(''))+'</div>'+(i>=4?'<p class="tiny">Introducción disponible. El desarrollo completo de esta etapa se ampliará en próximas versiones.</p>':'')+'</div>'}).join('')+'</div>'}
function songs(){return '<div class="eyebrow">LA PRÁCTICA SE CONVIERTE EN MÚSICA</div><h1>Pequeñas piezas, grandes pasos</h1><p class="intro">Piezas didácticas originales de Piano PRO. Escucha, separa las manos y une cada frase a tu ritmo.</p><div class="grid">'+lessons.filter(e=>e.song).map(e=>'<div class="card lesson"><span class="pill">ETAPA '+e.stage+' · '+e.meter.join('/')+'</span><h3>'+e.title+'</h3><p>'+e.desc+'</p><button class="btn primary" data-ex="'+e.id+'">Tocar esta pieza →</button></div>').join('')+'</div>'}
function harmony(){return '<div class="eyebrow">ENTENDER LO QUE TOCAS</div><h1>Teclado y armonía</h1><p class="intro">Descubre cómo se relacionan las notas. Escucha cada acorde y reconoce su dibujo sobre el teclado.</p><div class="card">'+keyboard()+'</div><div class="grid">'+[['Do mayor',[60,64,67],'Do · Mi · Sol'],['Fa mayor',[60,65,69],'Do · Fa · La · inversión'],['Sol mayor',[59,62,67],'Si · Re · Sol · inversión'],['La menor',[60,64,69],'Do · Mi · La · inversión'],['Re menor',[62,65,69],'Re · Fa · La'],['Sol séptima',[59,62,65,67],'Si · Re · Fa · Sol · inversión']].map(([t,n,d])=>'<div class="card"><h3>'+t+'</h3><p class="chord-keys">'+d+'</p><button class="btn" data-chord="'+n.join(',')+'">♫ Escuchar y ver</button></div>').join('')+'</div><div class="callout">Los acordes se muestran en posiciones concretas; la nota más grave puede ser distinta de la tónica. No son digitaciones obligatorias.</div>'}
function rhythm(){return '<div class="eyebrow">EL CORAZÓN DE LA MÚSICA</div><h1>Encuentra tu pulso</h1><p class="intro">Escucha, cuenta y toca. El metrónomo acompaña tu práctica y también te enseña a sostener el tiempo.</p><section class="card metro-card"><div class="metro-number" id="metro-number">'+bpm+'</div><div class="metro-unit" id="metro-unit">'+(metMeter==='6/8'?'Negra con puntillo':'Negra')+' por minuto</div><div class="controls"><label class="field">TEMPO<input id="metro-bpm" type="number" min="30" max="300" value="'+bpm+'"></label><label class="field">COMPÁS<select id="meter">'+['2/4','3/4','4/4','6/8'].map(m=>'<option '+(m===metMeter?'selected':'')+'>'+m+'</option>').join('')+'</select></label><label class="field">SUBDIVISIÓN<select id="metro-sub">'+[1,2,3,4].map(n=>'<option '+(n===metSub?'selected':'')+'>'+n+'</option>').join('')+'</select></label></div><div class="beat-line" id="metro-beats">'+Array.from({length:metMeter==='6/8'?2:Number(metMeter[0])},(_,i)=>'<span class="beat">'+(i+1)+'</span>').join('')+'</div><div class="row"><button class="btn primary" id="metro-start">▶ Iniciar metrónomo</button><button class="btn" id="tap">Marcar pulso</button><label class="tiny">Volumen <input id="volume" type="range" min="0" max="1" step=".05" value="'+volume+'"></label></div><div class="callout">'+(metMeter==='6/8'?'6/8: dos pulsos grandes de tres corcheas. Cuenta «1 la li · 2 la li». Elige subdivisión 3 para escuchar cada corchea.':'Cuenta cada pulso y destaca ligeramente el primero. Subdivisión 2: «1 y 2 y…».')+'</div></section><div class="grid two"><div class="card"><h3>1. Palmas y silencio</h3><p class="tiny muted">A 60 BPM, da una palmada en 1 y 3. Mantén el gesto interno en 2 y 4. Después repite con una sola tecla.</p><button class="btn" data-ex="silencios">Trabajar silencios →</button></div><div class="card"><h3>2. De tres a seis</h3><p class="tiny muted">Compara un vals en 3/4 con el balanceo de 6/8. Escucha la agrupación antes de tocar.</p><button class="btn" data-ex="seisocho">Explorar 6/8 →</button></div></div>'}
function startMetro(){if(metro){stop();return}stop();audio();metro=true;$('#metro-start').textContent='■ Detener';const token=run,n=metMeter==='6/8'?2:Number(metMeter[0]),dur=60/bpm/metSub;let next=ctx.currentTime+.08,k=0;timer=setInterval(()=>{while(next<ctx.currentTime+.12){click(next,k%(n*metSub)===0);const b=Math.floor(k/metSub)%n;later(()=>{if(run!==token)return;$$('#metro-beats .beat').forEach((el,i)=>el.classList.toggle('on',i===b))},Math.max(0,(next-ctx.currentTime)*1000));next+=dur;k++}},25)}
function addAttempt(a){state.attempts.push({at:Date.now(),id:current.id,bpm,hand,mode,...a});save()}
function progress(){const a=state.attempts,days=new Set(a.map(x=>new Date(x.at).toLocaleDateString('es-ES',{timeZone:'Europe/Madrid'}))).size;return '<div class="eyebrow">CADA PRÁCTICA CUENTA</div><h1>Mi progreso</h1><p class="intro">Tu historial, sin mezclar sensaciones con mediciones. Guardado en este navegador.</p><div class="grid"><div class="stat"><small>PRÁCTICAS REGISTRADAS</small><strong>'+a.length+'</strong><small>Autoevaluaciones y tomas MIDI</small></div><div class="stat"><small>DÍAS DE PRÁCTICA</small><strong>'+days+'</strong><small>Según fecha de Madrid</small></div><div class="stat"><small>EJERCICIOS EXPLORADOS</small><strong>'+new Set(a.map(x=>x.id)).size+' / '+lessons.length+'</strong><small>Explorado no significa consolidado</small></div></div><div class="card" style="margin-top:22px"><h2>Últimas prácticas</h2>'+(a.length?a.slice(-30).reverse().map(x=>'<div class="attempt"><span><b>'+esc(lessons.find(e=>e.id===x.id)?.title||x.id)+'</b><br><small>'+new Date(x.at).toLocaleString('es-ES',{timeZone:'Europe/Madrid'})+' · '+x.bpm+' BPM · '+(x.source==='midi'?'MIDI · '+(x.mode==='free'?'A mi ritmo':'Con tempo'):'Autoevaluación')+'</small></span><small>'+(x.source==='midi'?'Notas '+x.hits+'/'+x.total+(x.timing!=null?'<br>Entradas a tiempo '+x.timing+'%':''):'Me '+(x.rating==='dificil'?'cuesta':x.rating==='bien'?'sale con calma':'resulta cómodo'))+'</small></div>').join(''):'<p class="muted">Tu primera práctica empieza con una tecla. Guarda una valoración o completa una toma MIDI para verla aquí.</p>')+'</div><button class="btn" id="export">↓ Exportar progreso</button>'}
function library(){return '<div class="eyebrow">TU REPERTORIO PERSONAL</div><h1>Biblioteca</h1><p class="intro">Conserva tus partituras y materiales en este dispositivo. Los archivos se abren como referencia; no se transcriben automáticamente.</p><div class="card drop"><h3>Un lugar para tu música</h3><p class="tiny muted">PDF, PNG, JPG, WebP y MusicXML · Hasta 12 MB por archivo</p><input id="upload" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.musicxml,.xml" aria-label="Añadir archivo a la biblioteca"><p class="tiny muted">La práctica evaluable requiere notas y ritmos revisados. En esta versión se utiliza el catálogo original.</p></div><div class="card"><h2>Mis archivos</h2><div id="files"><p class="muted">Cargando…</p></div></div>'}
function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('piano-pro-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function fileOp(action,value,owner=profiles.currentId){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('files',action==='getAll'?'readonly':'readwrite'),s=tx.objectStore('files');let result;if(action==='getAll'){const r=s.getAll();r.onsuccess=()=>result=r.result.filter(f=>profiles.ownsFile(f,owner))}else if(action==='put'){s.put({...value,profileId:owner})}else if(action==='delete'){const r=s.get(value);r.onsuccess=()=>{if(r.result&&profiles.ownsFile(r.result,owner))s.delete(value)}}tx.oncomplete=()=>{d.close();resolve(result)};tx.onerror=()=>{d.close();reject(tx.error)}})}
let files=[];async function loadFiles(){const owner=profiles.currentId;try{const loaded=await fileOp('getAll',null,owner);if(owner!==profiles.currentId||!$('#files'))return;files=loaded;$('#files').innerHTML=files.length?files.map(f=>'<div class="file-row"><span>▤ '+esc(f.name)+'<br><small class="muted">'+(f.size/1024).toFixed(0)+' KB · Archivo original</small></span><button class="btn" data-open="'+f.id+'">Abrir</button><button class="btn" data-delete="'+f.id+'" aria-label="Eliminar '+esc(f.name)+'">×</button></div>').join(''):'<p class="muted">Todavía no has añadido archivos.</p>';$('#files').onclick=async e=>{const b=e.target.closest('button');if(!b||owner!==profiles.currentId)return;if(b.dataset.open){const f=files.find(f=>f.id===b.dataset.open),u=URL.createObjectURL(f.blob);window.open(u,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(u),60000)}if(b.dataset.delete&&confirm('¿Eliminar este archivo de la biblioteca de este dispositivo?')){await fileOp('delete',b.dataset.delete,owner);loadFiles()}}}catch{if(owner!==profiles.currentId||!$('#files'))return;$('#files').textContent='El navegador no permite guardar archivos en este momento.'}}
function teacher(){return '<div class="eyebrow">COMPRENDER, ESCUCHAR Y TOCAR</div><h1>Tu profesor de piano</h1><p class="intro">Orientación para practicar mejor. Empieza con una idea clara y llévala enseguida al teclado.</p><div class="card teacher">'+[['Una postura que te deje moverte','Centra la banqueta, apoya los pies y ajusta la altura para situar los codos aproximadamente al nivel del teclado. Relaja hombros y muñecas. No fuerces extensiones; si aparece dolor, detén el ejercicio.'],['Cómo leer la guía de Piano PRO','MD es mano derecha y MI izquierda. Do4 es el Do central (MIDI 60). Los dedos son 1 pulgar, 2 índice, 3 medio, 4 anular y 5 meñique en cada mano. S significa silencio. Cada duración se expresa en negras: 0,5 es corchea; 1 negra; 1,5 negra con puntillo; 2 blanca; 4 redonda.'],['El puente hacia la partitura','Activa Ambas para relacionar cada nota con su posición. Clave de Sol para el pentagrama superior y Fa para el inferior. Observa primero compás y ritmo; después altura y digitación. Las partituras iniciales están en Do mayor, sin alteraciones.'],['Estudiar por fragmentos','Escucha la frase, trabaja cada mano y une las dos a un tempo cómodo. Repite dos compases con una intención concreta. Después toca la frase completa sin detenerte por cada pequeño error.'],['El pedal: claridad antes que cantidad','Empieza sin pedal. Después explora sostener una armonía y levantar el pedal al cambiar para evitar mezclar sonidos. El sensor MIDI del pedal se comprobará con el instrumento; la v1 no puntúa pedal ni expresión.'],['Qué puede medir Piano PRO','MIDI permite observar notas y entradas. En modo libre no se puntúa velocidad. Con tempo se comparan ataques con el tiempo esperado; el retardo del dispositivo puede influir. No se miden postura, dedos, calidad de sonido ni interpretación artística. La entrada por micrófono queda para una ampliación.'],['Tu objetivo avanzado','Construye autonomía para preparar repertorio, acompañar y comprender armonía. Las etapas medias y avanzadas tienen ejercicios introductorios en esta edición y se ampliarán progresivamente. No hay equivalencia con un título oficial.']].map(([t,d],i)=>'<details '+(i===0?'open':'')+'><summary>'+t+'</summary><p>'+d+'</p></details>').join('')+'<p>Referencias: <a href="https://es.yamaha.com/es/musical-instruments/pianos/explore/musical-instrument-guide/piano/play/play002.html" target="_blank" rel="noopener">Yamaha · Postura</a> · <a href="https://www.abrsm.org/en-gb/piano" target="_blank" rel="noopener">ABRSM · Formación pianística</a> · <a href="https://www.trinitycollege.com/qualifications/music/grade-exams/piano/resources" target="_blank" rel="noopener">Trinity · Recursos</a></p></div>'}
function config(){const checks=[['sound','Sonido de piano seleccionado.'],['transpose','Transposición en 0.'],['normal','Teclado dual, percusión y acordes automáticos desactivados.'],['velocity','Sensibilidad revisada: mantén Sync/Vel durante 5 segundos para alternarla.'],['posture','Altura, postura y volumen cómodos.']];return '<div class="eyebrow">UN BUEN COMIENZO</div><h1>Mi piano · VEVOR BD-881D</h1><p class="intro">Prepara tu instrumento para que tecla, sonido y notación coincidan.</p><div class="card row between"><span>Perfil activo: <b>'+esc(profiles.profile().name)+'</b></span><button class="btn" data-page="perfiles">Cambiar o crear perfil →</button></div><div class="grid two"><div class="card"><h2>Antes de tocar</h2>'+checks.map(([id,t])=>'<label class="check"><input type="checkbox" data-check="'+id+'" '+(state.checks[id]?'checked':'')+'><span>'+t+'</span></label>').join('')+'<div class="callout">El manual indica sensibilidad desactivada al encender. Compruébala escuchando la misma nota con pulsaciones suaves y más firmes. Tempo del teclado: 30–300. Luces: Reproducir/LED durante 5 segundos.</div></div><div class="card"><h2>Conectar por MIDI</h2><p class="tiny muted">Conecta el teclado al dispositivo mediante la conexión MIDI/OTG adecuada. Autoriza el acceso y selecciona una entrada.</p><button class="btn primary" id="connect-midi">Conectar MIDI</button><p id="midi-status" class="tiny">'+esc(midiStatus)+'</p><select id="midi-input" aria-label="Entrada MIDI"><option>Conecta para ver las entradas</option></select><p id="midi-last" class="callout">Toca una nota para comprobar la conexión. No se envían órdenes para controlar las luces.</p><p class="tiny muted">La compatibilidad depende del navegador. Bluetooth MIDI, sensibilidad transmitida y pedal requieren prueba física. La app funciona sin conectar el piano.</p></div></div><div class="card"><h2>Preferencias y datos</h2><div class="controls"><label class="field">NOMBRES DE NOTAS<select id="names"><option value="sol">Do · Re · Mi</option><option value="letters" '+(state.names==='letters'?'selected':'')+'>C · D · E</option></select></label><label class="field">VOLUMEN DE LA APP<input id="volume" type="range" min="0" max="1" step=".05" value="'+volume+'"></label></div><div class="row"><button class="btn" id="export">↓ Exportar progreso</button><label class="btn">↑ Importar progreso<input id="import" type="file" accept="application/json,.json" hidden></label></div><p class="tiny muted">Progreso y biblioteca se guardan en este navegador. La exportación contiene historial y preferencias; los archivos de Biblioteca se conservan aparte. Sites y GitHub Pages tendrán datos separados: utiliza exportar e importar al trasladarte.</p></div>'}
async function connectMidi(){if(!navigator.requestMIDIAccess){toast('Este navegador no ofrece MIDI. Puedes seguir practicando y registrar tu valoración.');return}try{midiAccess=await navigator.requestMIDIAccess({sysex:false});const inputs=[...midiAccess.inputs.values()];midiStatus=inputs.length?'MIDI disponible · '+inputs[0].name:'MIDI autorizado · No hay entradas conectadas';const setup=()=>{const inputs=[...midiAccess.inputs.values()].filter(i=>i.state==='connected');if($('#midi-input')){$('#midi-input').innerHTML=inputs.map(i=>'<option value="'+esc(i.id)+'">'+esc(i.name||'Teclado MIDI')+'</option>').join('');$('#midi-input').onchange=()=>selectInput($('#midi-input').value)}selectInput(inputs[0]?.id);};midiAccess.onstatechange=setup;setup();if($('#midi-status'))$('#midi-status').textContent=midiStatus;toast(midiStatus)}catch{midiStatus='Acceso MIDI no disponible o denegado';toast(midiStatus)}}
function selectInput(id){held.clear();if(capture){capture=null;stop()}for(const input of midiAccess.inputs.values())input.onmidimessage=input.id===id?onMidi:null;midiStatus=id?'MIDI · '+(midiAccess.inputs.get(id)?.name||'Conectado'):'Sin teclado MIDI conectado';if($('#midi-status'))$('#midi-status').textContent=midiStatus}
function onMidi(e){const [s,p,v]=e.data,cmd=s&240;if(cmd===176){if(p===64&&$('#midi-last'))$('#midi-last').textContent='Pedal CC64 recibido · '+v;return}if(cmd===128||cmd===144&&v===0){held.delete(p);return}if(cmd!==144)return;held.add(p);if($('#midi-last'))$('#midi-last').textContent=noteName(p)+' · MIDI '+p+' · Velocidad '+v;highlight({notes:[...held],ids:[]});if(!capture)return;const now=performance.now();if(capture.mode==='free'){const g=capture.groups[capture.index];if(!g)return;if(g.notes.includes(p))capture.seen.add(p);else capture.errors++;if(g.notes.every(n=>capture.seen.has(n))){capture.hits+=g.notes.length;capture.index++;capture.seen.clear();if(capture.index===capture.groups.length){finishCapture();return}highlight(capture.groups[capture.index]);$('#practice-status').textContent='MIDI · Grupo '+(capture.index+1)+'/'+capture.groups.length}}else{if(now<capture.start)return;const elapsed=(now-capture.start)/1000,quarter=60/bpm/(current.meter[1]===8?1.5:1);let candidates=capture.expected.filter(n=>!n.hit&&n.p===p&&Math.abs(n.t*quarter-elapsed)<=Math.min(.5,quarter*.65));candidates.sort((a,b)=>Math.abs(a.t*quarter-elapsed)-Math.abs(b.t*quarter-elapsed));if(candidates.length){const n=candidates[0];n.hit=true;capture.hits++;const delta=Math.abs(n.t*quarter-elapsed);if(delta<=Math.min(.18,quarter*.25))capture.onTime++}else capture.errors++}}
function startCapture(){stop();if(!midiAccess||![...midiAccess.inputs.values()].some(i=>i.onmidimessage&&i.state==='connected')){toast('Conecta primero una entrada MIDI en Configuración.');return}const gs=groups();if(!gs.length){toast('Esta mano no tiene notas en este ejercicio. Selecciona la otra mano.');return}capture={mode,groups:gs,index:0,seen:new Set,hits:0,errors:0,total:gs.reduce((s,g)=>s+g.notes.length,0),onTime:0};if(mode==='free'){highlight(gs[0]);$('#practice-status').textContent='MIDI · Toca el grupo destacado, sin prisa';toast('Práctica libre iniciada. La app espera tus notas.')}else{audio();const q=60/bpm/(current.meter[1]===8?1.5:1),bar=current.meter[0]*4/current.meter[1],lead=bar*q;capture.start=performance.now()+lead*1000+120;capture.expected=gs.flatMap(g=>g.notes.map(p=>({p,t:g.t,hit:false})));let start=ctx.currentTime+.12;for(let t=0;t<bar+length();t+=(current.meter[1]===8?1.5:1))click(start+t*q,t%bar===0);$('#practice-status').textContent='Cuenta de entrada… toca con el clic';const token=run;later(()=>{if(run===token&&capture)finishCapture()},(lead+length()*q+.6)*1000)}$('#midi-practice').textContent='■ Terminar toma'}
function finishCapture(){const c=capture;if(!c)return;capture=null;addAttempt({source:'midi',mode:c.mode,hits:c.hits,total:c.total,errors:c.errors,timing:c.mode==='timed'?Math.round(c.onTime/c.total*100):null});stop();$('#midi-practice').textContent='◎ Practicar con MIDI';$('#practice-status').textContent='Guardado · Notas '+c.hits+'/'+c.total+' · Extras '+c.errors+(c.mode==='timed'?' · A tiempo '+Math.round(c.onTime/c.total*100)+'%':' · Sin evaluar velocidad');toast('Toma MIDI guardada. Consulta el detalle en Mi progreso.')}
function bind(){const on=(id,event,fn)=>{const el=$(id);if(el)el.addEventListener(event,fn)};on('#exercise','change',e=>choose(e.target.value));on('#hand','change',e=>{stop();capture=null;hand=e.target.value;state.hand=hand;save();render()});on('#mode','change',e=>{stop();capture=null;mode=e.target.value;state.mode=mode;save();render()});on('#bpm','change',e=>{stop();capture=null;bpm=clamp(e.target.value);state.bpm=bpm;save();e.target.value=bpm});on('#play','click',()=>{capture=null;play()});on('#sub','change',e=>{stop();sub=Number(e.target.value)});on('#loop','change',e=>loop=e.target.checked);on('#midi-practice','click',()=>capture?finishCapture():startCapture());on('#rate','click',()=>{$('#rating').innerHTML='<p class="tiny muted">Autoevaluación · Sin medición'+'</p><div class="rating"><button class="btn" data-rating="dificil">Me cuesta</button><button class="btn" data-rating="bien">Me sale con calma</button><button class="btn" data-rating="comodo">Me resulta cómodo</button></div>'});on('#duration','change',e=>{state.duration=Number(e.target.value);save();render()});on('#connect-midi','click',connectMidi);on('#names','change',e=>{state.names=e.target.value;save();render()});on('#volume','input',e=>{volume=Number(e.target.value);state.volume=volume;save()});on('#export','click',exportData);on('#create-profile','submit',createProfile);on('#edit-profile','submit',editProfile);on('#import','change',importData);on('#upload','change',async e=>{const owner=profiles.currentId;const f=e.target.files[0];if(!f)return;if(f.size>12*1024*1024){toast('El archivo supera 12 MB.');return}try{await fileOp('put',{id:freshId(),name:f.name,size:f.size,blob:f},owner);if(owner===profiles.currentId){loadFiles();toast('Archivo guardado en este perfil.')}}catch{toast('No se ha podido guardar el archivo. Comprueba el espacio disponible.')}});on('#metro-start','click',startMetro);on('#metro-bpm','change',e=>{stop();bpm=clamp(e.target.value);render()});on('#meter','change',e=>{stop();metMeter=e.target.value;render()});on('#metro-sub','change',e=>{stop();metSub=Number(e.target.value)});on('#tap','click',()=>{const now=performance.now();taps=taps.filter(t=>now-t<5000);taps.push(now);if(taps.length>1){bpm=clamp(60000/((now-taps[0])/(taps.length-1)));$('#metro-number').textContent=bpm;$('#metro-bpm').value=bpm;if(metro)stop()}});$$('[data-check]').forEach(el=>el.onchange=()=>{state.checks[el.dataset.check]=el.checked;save()});$$('[data-key]').forEach(el=>el.addEventListener('pointerdown',e=>{e.preventDefault();audio();tone(Number(el.dataset.key),ctx.currentTime,.7);el.classList.add('lit');setTimeout(()=>el.classList.remove('lit'),450)}))}
let taps=[];function clamp(n){return Math.min(300,Math.max(30,Math.round(Number(n)||60)))}
function choose(id){stop();capture=null;current=lessons.find(e=>e.id===id)||lessons[0];bpm=current.bpm;hand='both';state.lastExercise=current.id;state.bpm=bpm;state.hand=hand;save();page='practicar';location.hash=page;render();window.scrollTo(0,0)}
function avatarOptions(selected='🎹'){return AVATARS.map(a=>'<option '+(a===selected?'selected':'')+'>'+a+'</option>').join('')}
function profilePage(){const active=profiles.profile();return '<div class="eyebrow">UN ESPACIO PARA CADA PERSONA</div><h1>¿Quién toca hoy?</h1><p class="intro">Cada perfil conserva su progreso, recomendaciones AIA, preferencias y biblioteca en este navegador.</p><div class="profile-grid">'+profiles.list().map(p=>'<button class="profile-card '+(p.id===profiles.currentId?'selected':'')+'" data-profile="'+esc(p.id)+'"><span class="profile-avatar">'+esc(p.avatar)+'</span><strong>'+esc(p.name)+'</strong><small>'+(p.id===profiles.currentId?'✓ Perfil activo':'Entrar en este perfil →')+'</small></button>').join('')+'</div><div class="grid two"><form class="card" id="create-profile"><h2>Crear un perfil</h2><label class="field">NOMBRE<input name="name" maxlength="40" required placeholder="Nombre de la persona" autocomplete="off"></label><label class="field">AVATAR<select name="avatar">'+avatarOptions()+'</select></label><button class="btn primary" type="submit">Crear y entrar →</button></form><form class="card" id="edit-profile"><h2>Editar mi perfil</h2><label class="field">NOMBRE<input name="name" maxlength="40" required value="'+esc(active.name)+'" autocomplete="off"></label><label class="field">AVATAR<select name="avatar">'+avatarOptions(active.avatar)+'</select></label><button class="btn" type="submit">Guardar cambios</button></form></div><div class="card"><h3>Tu progreso anterior está a salvo</h3><p class="tiny muted">Los datos de la primera versión se conservan en «Perfil inicial», que puedes renombrar. Los nuevos perfiles empiezan sin historial. Exportar e importar afecta únicamente al perfil activo; los archivos de Biblioteca se trasladan aparte.</p><button class="btn" id="export">↓ Exportar este perfil</button><label class="btn">↑ Importar en este perfil<input id="import" type="file" accept="application/json,.json" hidden></label></div><div class="callout">Perfiles locales, sin contraseña ni sincronización. Las personas que comparten el navegador pueden seleccionar cualquier perfil.</div>'}
function switchProfile(id){if(id===profiles.currentId){navigate('practicar');return}if(!save())return;try{stop();held.clear();state=profiles.select(id);view=state.view;volume=state.volume??.5;hand=state.hand||'both';mode=state.mode||'free';current=lessons.find(e=>e.id===state.lastExercise)||lessons[0];bpm=state.bpm||current.bpm;sub=1;loop=false;files=[];taps=[];metMeter='4/4';metSub=1;navigate('practicar');toast('Ahora toca '+profiles.profile().name)}catch{toast('No se ha podido abrir el perfil. Comprueba el almacenamiento del navegador.')}}
function createProfile(e){e.preventDefault();try{const f=new FormData(e.target),p=profiles.create(f.get('name'),f.get('avatar'));switchProfile(p.id)}catch(err){toast(err.message||'No se ha podido crear el perfil.')}}
function editProfile(e){e.preventDefault();try{const f=new FormData(e.target);profiles.update(f.get('name'),f.get('avatar'));render();toast('Perfil actualizado.')}catch(err){toast(err.message||'No se ha podido actualizar.')}}
function exportData(){const blob=new Blob([JSON.stringify({...state,app:'piano-pro',version:2,profile:{name:profiles.profile().name,avatar:profiles.profile().avatar}},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='piano-pro-'+profiles.profile().name.replace(/[^a-z0-9áéíóúñ_-]/gi,'_')+'-progreso.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function importData(e){const owner=profiles.currentId;try{const d=JSON.parse(await e.target.files[0].text());if(d.app!=='piano-pro'||!Array.isArray(d.attempts)||d.attempts.length>10000||d.attempts.some(a=>!lessons.some(l=>l.id===a.id)||!Number.isFinite(a.at)||!Number.isFinite(a.bpm)||a.bpm<30||a.bpm>300||!['manual','midi'].includes(a.source)||!['free','timed'].includes(a.mode)||!['r','l','both'].includes(a.hand)||(a.source==='manual'&&!['dificil','bien','comodo'].includes(a.rating))||(a.source==='midi'&&(!Number.isFinite(a.hits)||!Number.isFinite(a.total)||a.hits<0||a.hits>a.total||a.total<=0||(a.timing!==null&&(!Number.isFinite(a.timing)||a.timing<0||a.timing>100))))))throw Error();if(owner!==profiles.currentId){toast('El perfil ha cambiado. Repite la importación en el perfil deseado.');return}const merged=new Map([...state.attempts,...d.attempts].map(a=>[a.at+'-'+a.id,a]));state.attempts=[...merged.values()].sort((a,b)=>a.at-b.at);if(['guide','score','both'].includes(d.view))state.view=d.view;if(['sol','letters'].includes(d.names))state.names=d.names;if([10,15,20,30].includes(d.duration))state.duration=d.duration;if(typeof d.volume==='number'&&d.volume>=0&&d.volume<=1)state.volume=d.volume;view=state.view;volume=state.volume;if(save()){toast('Importado en '+profiles.profile().name+' sin duplicar registros.');render()}}catch{toast('No es un archivo de progreso válido de Piano PRO.')}}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-page]');if(!b)return;if(b.dataset.profile){switchProfile(b.dataset.profile);return}if(b.dataset.page){navigate(b.dataset.page)}if(b.dataset.ex)choose(b.dataset.ex);if(b.dataset.view){stop();capture=null;view=b.dataset.view;state.view=view;save();render()}if(b.dataset.rating){addAttempt({source:'manual',rating:b.dataset.rating});$('#rating').innerHTML='<p class="score-label">✓ Valoración guardada · Autoevaluación, sin medición</p>';toast('Práctica guardada. AIA la tendrá en cuenta.')}if(b.dataset.chord){stop();audio();const ps=b.dataset.chord.split(',').map(Number);ps.forEach(p=>tone(p,ctx.currentTime,.9));highlight({notes:ps,ids:[]})}});
function navigate(id){stop();capture=null;menu=false;$('.modal-nav')?.remove();page=id;location.hash=id;render();window.scrollTo(0,0)}
$('#menu-button').onclick=()=>{menu=!menu;$('.modal-nav')?.remove();if(menu){const d=document.createElement('div');d.className='modal-nav';d.innerHTML='<h2>Tu estudio</h2>'+pages.map(([id,ic,t])=>'<button class="nav-item" data-page="'+id+'">'+navIcon(id)+'<span>'+t+'</span>'+'</button>').join('')+'<button class="nav-item" data-page="config">' +navIcon('config')+'<span>Mi piano y configuración</span></button>';document.body.append(d)}};
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(p!==page&&(pages.some(x=>x[0]===p)||p==='config'))navigate(p)});document.addEventListener('visibilitychange',()=>{if(document.hidden){const hadCapture=!!capture;stop();if(hadCapture)toast('Toma interrumpida al salir de la pestaña; no se ha guardado.')}});
page=pages.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'practicar';render();
